def split_bucket(ctx):
    bits = [int(ctx[k]) for k in ('lineage_verified', 'dependency_lock_verified', 'evidence_fetch_hardened', 'historical_state_protected', 'current_generation_active')]
    return (bits[0] + bits[1] + bits[2] + bits[3] + 2 * bits[4]) % 4

